import fs from "node:fs";

import { API_URL } from "../../playwright.config";
import { expect, sample, test, uniqueName } from "../../fixtures";

test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
  // Arrange: a draft vendor whose only document is an extracted W-9
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Missing Docs"),
      category: "services",
      contact_email: `ops.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = (await vendorRes.json()) as { id: string };

  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.txt",
        mimeType: "text/plain",
        buffer: fs.readFileSync(sample("w9.txt")),
      },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const document = (await uploadRes.json()) as { id: string };

  // Extraction runs in the background; wait until the W-9 is extracted.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${document.id}`);
        return ((await res.json()) as { status: string }).status;
      },
      { timeout: 30_000 },
    )
    .toBe("extracted");

  // Act
  const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  expect(submitRes.status(), await submitRes.text()).toBe(409);
  const body = (await submitRes.json()) as {
    error: { code: string; missing_kinds: string[] };
  };
  expect(body.error.code, JSON.stringify(body)).toBe("documents_incomplete");
  expect(body.error.missing_kinds, JSON.stringify(body)).toEqual([
    "contract",
    "insurance_certificate",
  ]);
});
